window.SEARCH_INDEX=[{"g": "harmonies", "u": "harmonies/", "a": "h-setup", "t": "Setup checklist", "s": "Section", "k": "section", "x": "Setup checklist Put the central board in the middle and pour all colored tokens into the pouch. Draw 3 tokens at random onto each of the 5 spaces of the central board. Shuffle the Animal cards and lay 5 face up beside the board (the “river” of cards). Keep the Animal cubes in a general supply. Each player takes a personal board. Agree on a side: Side A (scores rivers) or Side B (scores islands). E"}, {"g": "harmonies", "u": "harmonies/", "a": "h-turn", "t": "Your turn, step by step", "s": "Section", "k": "section", "x": "Your turn, step by step ← Back Next →"}, {"g": "harmonies", "u": "harmonies/", "a": "h-turn--1", "t": "Take 3 tokens", "s": "Your turn, step by step", "k": "rule", "x": ""}, {"g": "harmonies", "u": "harmonies/", "a": "h-turn--2", "t": "Take an Animal card", "s": "Your turn, step by step", "k": "rule", "x": ""}, {"g": "harmonies", "u": "harmonies/", "a": "h-turn--3", "t": "Place Animal cubes", "s": "Your turn, step by step", "k": "rule", "x": ""}, {"g": "harmonies", "u": "harmonies/", "a": "h-turn--4", "t": "Refill", "s": "Your turn, step by step", "k": "rule", "x": ""}, {"g": "harmonies", "u": "harmonies/", "a": "h-stack", "t": "Stacking checker", "s": "Section", "k": "section", "x": "Stacking checker Token you want to place What's on that space right now? Empty space 1 gray 2 gray 3 gray 1 brown 2 brown Brown + green (tree) 1 green 1 red Gray + red (building) Brown + red (building) Red + red (building) Blue Yellow Any token with an Animal cube on it Token Can go on Max Gray (mountain) Empty space or gray 3 high Brown (trunk) Empty space or 1 brown 2 high Green (leaves) Empty, "}, {"g": "harmonies", "u": "harmonies/", "a": "h-rules", "t": "Rules detail", "s": "Section", "k": "section", "x": "Rules detail"}, {"g": "harmonies", "u": "harmonies/", "a": "h-trees-green-on-brown", "t": "Trees (green on brown)", "s": "Rules detail", "k": "rule", "x": "A green token on its own or on top of 1 or 2 brown tokens is a tree. Height 1 2 3 Points 1 3 7"}, {"g": "harmonies", "u": "harmonies/", "a": "h-mountains-gray-stacks", "t": "Mountains (gray stacks)", "s": "Rules detail", "k": "rule", "x": "A stack of 1–3 gray tokens. It only scores if it's next to at least one other mountain . A lone mountain scores 0. Height 1 2 3 Points 1 3 7"}, {"g": "harmonies", "u": "harmonies/", "a": "h-fields-yellow-groups", "t": "Fields (yellow groups)", "s": "Rules detail", "k": "rule", "x": "Each group of 2 or more connected yellow tokens scores 5 points, no matter how big it is. Several small groups beat one big group."}, {"g": "harmonies", "u": "harmonies/", "a": "h-buildings-red-on-top", "t": "Buildings (red on top)", "s": "Rules detail", "k": "rule", "x": "A red token on top of a gray, brown or red token is a building. It scores 5 points if the spaces around it show at least 3 different colors (look at the top token of each stack)."}, {"g": "harmonies", "u": "harmonies/", "a": "h-water-side-a-rivers", "t": "Water – Side A: Rivers", "s": "Rules detail", "k": "rule", "x": "Score only your single longest river : a chain of connected blue tokens, counted end to end. Length 1 2 3 4 5 6 7+ Points 0 2 5 8 11 15 +4 each"}, {"g": "harmonies", "u": "harmonies/", "a": "h-water-side-b-islands", "t": "Water – Side B: Islands", "s": "Rules detail", "k": "rule", "x": "Blue tokens divide your board into separate land areas. Each island (a group of non-water tokens cut off from the others by water or the board edge) scores 5 points ."}, {"g": "harmonies", "u": "harmonies/", "a": "h-animal-cards-and-habitats", "t": "Animal cards and habitats", "s": "Rules detail", "k": "rule", "x": "Each card shows a habitat pattern (token colors and heights) and a track of cubes with point values. The pattern must match exactly, including stack heights. You can rotate it. The cube goes on the highlighted token of the pattern. At game end, each card scores the highest point value you've uncovered on its track. Unfinished cards still score what you've uncovered. Cube placement is final, even if later tokens change the area around it."}, {"g": "harmonies", "u": "harmonies/", "a": "h-card-limit", "t": "Card limit", "s": "Rules detail", "k": "rule", "x": "You can have at most 4 unfinished cards in front of you. Once every cube on a card is placed, set the card aside. It no longer counts toward the limit."}, {"g": "harmonies", "u": "harmonies/", "a": "h-nature-s-spirit-variant", "t": "Nature's Spirit variant", "s": "Rules detail", "k": "rule", "x": "Recommended once you know the game. At setup each player draws Spirit cards and keeps one. A Spirit card works like an Animal card with a single cube. Once its cube is placed, it gives a special end-game scoring bonus. It counts toward the 4-card limit until it's finished."}, {"g": "harmonies", "u": "harmonies/", "a": "h-solo-mode", "t": "Solo mode", "s": "Rules detail", "k": "rule", "x": "Harmonies includes a solo mode where you play to beat score targets. The rulebook covers the small setup and refill changes. Keep your rulebook nearby for the exact solo steps."}, {"g": "harmonies", "u": "harmonies/", "a": "h-end", "t": "Game end and winning", "s": "Section", "k": "section", "x": "Game end and winning The end is triggered when… the pouch can't refill the central board, or at the end of a player's turn, their board has 2 or fewer empty spaces . Finish the round so everyone has played the same number of turns. Winner Most points wins. Tie: the tied player who placed the most Animal cubes wins. If still tied, they share the victory."}, {"g": "harmonies", "u": "harmonies/", "a": "h-calc", "t": "Score calculator", "s": "Section", "k": "section", "x": "Score calculator Board side Side A · Rivers Side B · Islands Trees, height 1 Trees, height 2 Trees, height 3 Mountains h1 (adjacent) Mountains h2 (adjacent) Mountains h3 (adjacent) Fields (groups of 2+) Scoring buildings Longest river length Number of islands Animal card points (sum) Spirit card points 0 Clear"}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-win", "t": "How you win or lose", "s": "Section", "k": "section", "x": "How you win or lose You win Defeat the Boss in Act 2, inside its Lair. You lose if any of these happen A 5th Goblin has to be placed. The torch reaches the skull at the end of its track. No open corridors are left to explore and the Lair Door hasn't been found ."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-setup", "t": "Setup checklist", "s": "Section", "k": "section", "x": "Setup checklist Build the Dungeon deck in three stacks, top to bottom. Top: Room cards (2 heroes: 9 · 3 heroes: 7 · 4 heroes: 5). Middle: 1 Encounter card + 3 Room cards per hero, shuffled. Bottom: 3 Room cards shuffled with the Lair Door. Place the Entrance card face up in the middle with 4 face-down cards around it. The dungeon can grow up to a 7×7 grid. Put 1 Altar marker on the Entrance. Set a"}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-turn", "t": "Your turn, step by step", "s": "Section", "k": "section", "x": "Your turn, step by step ← Back Next →"}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-turn--1", "t": "Move", "s": "Your turn, step by step", "k": "rule", "x": ""}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-turn--2", "t": "1 Heroic Action", "s": "Your turn, step by step", "k": "rule", "x": ""}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-turn--3", "t": "Free Actions", "s": "Your turn, step by step", "k": "rule", "x": ""}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-turn--4", "t": "Move the torch", "s": "Your turn, step by step", "k": "rule", "x": ""}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-rules", "t": "Rules detail", "s": "Section", "k": "section", "x": "Rules detail"}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-hero-attributes", "t": "Hero attributes", "s": "Rules detail", "k": "rule", "x": "Health: below 1 means you're unconscious. Focus: pays for abilities and die changes. It can't go below 0. Speed: the most rooms you can enter in a turn. Defense: how much damage you cancel from a counter-attack. Skills: Strength, Agility, Intellect: how many dice you roll for a check (always 1–3, never a 4th)."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-skill-checks", "t": "Skill checks", "s": "Rules detail", "k": "rule", "x": "Roll as many Hero dice as your skill (1–3). Pick one die as your result. +1/+2 modifiers add to it. If you succeed, unused dice showing Focus give you Focus, and unused 6s give you Health. Attacks also roll the Enemy die when the target can see you (same room or line of sight)."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-check-for-danger-newly-revealed-rooms", "t": "Check for danger (newly revealed rooms)", "s": "Rules detail", "k": "rule", "x": "Goblin icon: take 1 damage and stop. Draw a Goblin onto the Torch mat and put its token in that room. Minion icon: take 2 damage and stop. Draw a Minion, set its Health marker to the top of its track, and put its token in the room. Trap: make the evasion check on the left side of the card, and take the damage shown if you fail. Then you can keep moving or try to disarm it."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-attacking-and-damage", "t": "Attacking and damage", "s": "Rules detail", "k": "rule", "x": "Melee: a target in your room. Missile: a target in another room in line of sight. Spell: targets within the spell's range. Spell damage ignores Defense. Damage dealt = your check total minus the enemy's Defense. Goblins have 1 Health. Minions track Health on their card. Killing a Minion: gain loot or spells twice, move the torch up 6 (never above its start), and put its Health marker on the Boss mat."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-enemy-counter-attack", "t": "Enemy counter-attack", "s": "Rules detail", "k": "rule", "x": "If the enemy survives and can see you, it hits back using the Enemy die: 2–5: the die plus the enemy's modifier for your attack type. Shield: just the enemy's modifier as damage. Torch: a miss, but the torch moves down 1. Subtract your Defense. Whatever is left is the damage you take."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-unconscious-heroes", "t": "Unconscious heroes", "s": "Rules detail", "k": "rule", "x": "At 0 Health your turn ends. Lay your miniature down. On your next turn you must Rest , then you may move. No Free Actions that turn. Healing from another hero wakes you up right away. Starting your turn unconscious alone with a monster does not lose the game. That was a pre-release rule."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-loot-spells-and-equipment-limits", "t": "Loot, spells and equipment limits", "s": "Rules detail", "k": "rule", "x": "You can only equip a card when an effect lets you discover it or pick it up. You can discard one at any time as a Free Action. Limits: 1 Garb, 2 Hand, 2 Spells, 2 Trinkets . Pieces of a Legendary Set give a bonus from 2 pieces, and more as you collect more."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-enemy-movement-goblins-and-minions", "t": "Enemy movement (Goblins and Minions)", "s": "Rules detail", "k": "rule", "x": "Goblins attack if a hero is in their room. Otherwise they move. Each one deals damage equal to the number of Goblins in play, plus 1 if it's attacking. Minions move toward the nearest conscious hero by the shortest path, stop at the first room with a hero, then attack."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-entering-the-lair-act-2", "t": "Entering the Lair (Act 2)", "s": "Rules detail", "k": "rule", "x": "When the Lair Door is revealed and every Minion is dead, step from the Lair Door onto the Boss mat's entrance (1 Speed). Then: Flip the Boss mat to Act 2. Stack all Minion Health markers on the 8 space. Place the Boss token in the Lair. Flip the Torch mat to Act 2 and put the torch on the top space for your hero count. Place Altar markers on each Minion encounter."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-the-boss-fight", "t": "The Boss fight", "s": "Rules detail", "k": "rule", "x": "Heroes stand on Hero Spaces to attack. Some spaces give a bonus, but only when you end your movement there. Only 1 hero per space. Each Minion Health marker takes damage separately. A marker can't pass an uncovered Altar. When the Boss enters an Altar room, it moves to the highest uncovered Altar and that marker comes off. Taunt (2 Focus, repeatable) pulls the Boss toward you. Missile and spell attacks from outside can't reach the Boss in its Lair. You can leave the Lair through its entrance. In Act 2, when the torch passes an Enemy Action, the Boss acts after the Goblins."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-solo-play", "t": "Solo play", "s": "Rules detail", "k": "rule", "x": "Control at least 2 heroes, tracking each one's stats, gear and position separately. Your hero count, not your player count, sets the setup numbers."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-faq-quick-hits", "t": "FAQ quick hits", "s": "Rules detail", "k": "rule", "x": "Do I have to do anything on my turn? No, but the torch still moves down. Can I act in any order? Yes. Move, Heroic Action and Free Actions can happen in any order. Free Actions on someone else's turn? No. Same Free Action twice? Yes, if you can pay for it. Torch higher than its start? Never."}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-tools", "t": "Combat helper", "s": "Section", "k": "section", "x": "Combat helper Your attack Your check total Enemy Defense Spell attack (ignores Defense) 3 Enemy counter-attack Enemy die result 2 3 4 5 🛡 Shield 🔥 Torch Enemy modifier (vs your attack type) Your Defense 3"}, {"g": "ted", "u": "tiny-epic-dungeons/", "a": "t-track", "t": "Danger tracker", "s": "Section", "k": "section", "x": "Danger tracker Goblins in play − 0 + Turn counter − 0 + Reset"}, {"g": "century", "u": "century-golem/", "a": "c-setup", "t": "Setup checklist", "s": "Section", "k": "section", "x": "Setup checklist Shuffle the Golem (point) cards and lay 5 face up in a row. Put gold coins (2 × players) above the 1st golem and silver coins (2 × players) above the 2nd. Shuffle the Merchant cards and lay 6 face up in a row below the golems. Fill the 4 bowls with yellow, green, blue and pink crystals. Each player takes a Caravan card and the 2 starting cards: Create 2 yellow and Upgrade 2 . Choos"}, {"g": "century", "u": "century-golem/", "a": "c-crystals", "t": "Crystal ladder", "s": "Section", "k": "section", "x": "Crystal ladder Yellow → Green → Blue → Pink Each upgrade moves one crystal up one step . With “Upgrade 2” you can turn two yellows into two greens, or one yellow into a blue. At game end, every non-yellow crystal left in your caravan is worth 1 point ."}, {"g": "century", "u": "century-golem/", "a": "c-turn", "t": "Your turn: pick exactly ONE action", "s": "Section", "k": "section", "x": "Your turn: pick exactly ONE action ← Back Next →"}, {"g": "century", "u": "century-golem/", "a": "c-turn--1", "t": "Play a card", "s": "Your turn: pick exactly ONE action", "k": "rule", "x": ""}, {"g": "century", "u": "century-golem/", "a": "c-turn--2", "t": "Acquire a card", "s": "Your turn: pick exactly ONE action", "k": "rule", "x": ""}, {"g": "century", "u": "century-golem/", "a": "c-turn--3", "t": "Rest", "s": "Your turn: pick exactly ONE action", "k": "rule", "x": ""}, {"g": "century", "u": "century-golem/", "a": "c-turn--4", "t": "Claim a golem", "s": "Your turn: pick exactly ONE action", "k": "rule", "x": ""}, {"g": "century", "u": "century-golem/", "a": "c-turn--5", "t": "End of turn", "s": "Your turn: pick exactly ONE action", "k": "rule", "x": ""}, {"g": "century", "u": "century-golem/", "a": "c-rules", "t": "Rules detail", "s": "Section", "k": "section", "x": "Rules detail"}, {"g": "century", "u": "century-golem/", "a": "c-caravan-limit-10-crystals", "t": "Caravan limit (10 crystals)", "s": "Rules detail", "k": "rule", "x": "You can go over 10 during your turn. At the end of your turn, discard down to 10, keeping whichever crystals you like."}, {"g": "century", "u": "century-golem/", "a": "c-crystal-supply", "t": "Crystal supply", "s": "Rules detail", "k": "rule", "x": "The crystal supply is unlimited. If a color runs out, use something else as a stand-in."}, {"g": "century", "u": "century-golem/", "a": "c-trade-cards-repeating-trades", "t": "Trade cards – repeating trades", "s": "Rules detail", "k": "rule", "x": "One play of a Trade card lets you make the exchange as many times as you can pay for it. Example: a “2 yellow → 1 blue” card with 6 yellows can give you 3 blues."}, {"g": "century", "u": "century-golem/", "a": "c-acquiring-paying-the-cards-to-the-left", "t": "Acquiring – paying the cards to the left", "s": "Rules detail", "k": "rule", "x": "To take the 4th card, put one crystal each on cards 1, 2 and 3. Crystals left on a card go to whoever takes it later, so cheap cards can come with free crystals."}, {"g": "century", "u": "century-golem/", "a": "c-coins", "t": "Coins", "s": "Rules detail", "k": "rule", "x": "Gold = 3 points, silver = 1 point. You only get one when you claim the golem in the 1st (gold) or 2nd (silver) spot. Once the gold is gone, silver moves to the 1st spot and the 2nd spot pays nothing."}, {"g": "century", "u": "century-golem/", "a": "c-strategy-tips", "t": "Strategy tips", "s": "Rules detail", "k": "rule", "x": "Early on, cheap Upgrade and good Trade cards build a strong engine. Don't rest too often. Each rest is a turn without crystals. Keep an eye on the coins. Grabbing the 1st golem is worth 3 extra points. Leftover blue and pink crystals score at the end, so don't waste them."}, {"g": "century", "u": "century-golem/", "a": "c-end", "t": "Game end and winning", "s": "Section", "k": "section", "x": "Game end and winning The end is triggered when a player claims their… 5th golem with 4–5 players 6th golem with 2–3 players Finish the current round so everyone has the same number of turns. Scoring Golem points + coins (gold 3, silver 1) + 1 point per non-yellow crystal . Tie: the tied player who went later in turn order wins."}, {"g": "century", "u": "century-golem/", "a": "c-calc", "t": "Score sheet", "s": "Section", "k": "section", "x": "Score sheet Player (seat order) Golem pts Gold coins Silver coins Non-yellow crystals Total + Player − Player Clear"}, {"g": "night", "u": "game-night/", "a": "p-share", "t": "Share with a QR code", "s": "Section", "k": "section", "x": "Share with a QR code Scan to open the rulebook Copy link"}, {"g": "night", "u": "game-night/", "a": "p-me", "t": "My player", "s": "Section", "k": "section", "x": "My player Nickname Pick your token Save my player"}, {"g": "night", "u": "game-night/", "a": "p-room", "t": "Room", "s": "Section", "k": "section", "x": "Room Host a game Which game? 🌿 Harmonies 🗡️ Tiny Epic Dungeons 💎 Century Create room code Join with a code Room code Join room"}, {"g": "night", "u": "game-night/", "a": "p-board", "t": "Leaderboard", "s": "Section", "k": "section", "x": "Leaderboard All games 🌿 Harmonies 🗡️ TED 💎 Century Recent games"}, {"g": "wingspan", "u": "wingspan/", "a": "w-setup", "t": "Setup checklist", "s": "Section", "k": "section", "x": "Setup checklist Shuffle the bird cards into a deck and put 3 face up in the bird tray. Put all food tokens and eggs in a shared supply. Toss the 5 food dice into the birdfeeder dice tower. Pick a goal board side: green (players compete for 1st, 2nd and 3rd) or blue (1 point per item, up to 5). Place 1 random goal tile on each of the 4 round spaces. Shuffle the bonus cards into a deck. Each player "}, {"g": "wingspan", "u": "wingspan/", "a": "w-turn", "t": "Your turn: pick ONE of four actions", "s": "Section", "k": "section", "x": "Your turn: pick ONE of four actions ← Back Next →"}, {"g": "wingspan", "u": "wingspan/", "a": "w-turn--1", "t": "Play a bird", "s": "Your turn: pick ONE of four actions", "k": "rule", "x": ""}, {"g": "wingspan", "u": "wingspan/", "a": "w-turn--2", "t": "Gain food (forest)", "s": "Your turn: pick ONE of four actions", "k": "rule", "x": ""}, {"g": "wingspan", "u": "wingspan/", "a": "w-turn--3", "t": "Lay eggs (grassland)", "s": "Your turn: pick ONE of four actions", "k": "rule", "x": ""}, {"g": "wingspan", "u": "wingspan/", "a": "w-turn--4", "t": "Draw cards (wetland)", "s": "Your turn: pick ONE of four actions", "k": "rule", "x": ""}, {"g": "wingspan", "u": "wingspan/", "a": "w-rounds", "t": "Rounds and actions", "s": "Section", "k": "section", "x": "Rounds and actions Round Turns each Why 1 8 All 8 cubes 2 7 1 cube is on the goal board 3 6 2 cubes on the goal board 4 5 3 cubes on the goal board End of each round Score the round's goal on the goal board with one of your cubes. Take all action cubes back off your player mat. Discard the 3 face-up birds in the tray and deal 3 new ones. Pass the first-player token clockwise."}, {"g": "wingspan", "u": "wingspan/", "a": "w-rules", "t": "Rules detail", "s": "Section", "k": "section", "x": "Rules detail"}, {"g": "wingspan", "u": "wingspan/", "a": "w-egg-cost-by-column", "t": "Egg cost by column", "s": "Rules detail", "k": "rule", "x": "The column a new bird goes into sets its egg cost, whichever habitat it's in. Column 1 2 3 4 5 Eggs 0 1 1 2 2 Each habitat row holds at most 5 birds, filled from left to right."}, {"g": "wingspan", "u": "wingspan/", "a": "w-paying-food", "t": "Paying food", "s": "Rules detail", "k": "rule", "x": "Pay the food shown in the bird's top-left corner from your personal supply. A wild food icon can be paid with any food type. Any 2 food tokens can be spent as 1 food of any type. Some birds show “/” between foods: pay either one."}, {"g": "wingspan", "u": "wingspan/", "a": "w-the-birdfeeder-and-dice", "t": "The birdfeeder and dice", "s": "Rules detail", "k": "rule", "x": "Taking food means taking a die out of the birdfeeder. Dice stay out until the feeder is rerolled. If the birdfeeder is empty , reroll all 5 dice. If every die left shows the same face , even just 1 die, you may reroll all 5 dice before you take food. You can do this partway through gaining food too. The invertebrate/seed face counts as its own face, and you can take it as either food."}, {"g": "wingspan", "u": "wingspan/", "a": "w-bird-powers-white-brown-and-pink", "t": "Bird powers: white, brown and pink", "s": "Rules detail", "k": "rule", "x": "White, “When played”: happens once, right after you play the bird. Brown, “When activated”: happens each time you use that bird's habitat row. Activate them right to left. Each is optional. Pink, “Once between turns”: triggers during another player's turn, at most once between your own turns."}, {"g": "wingspan", "u": "wingspan/", "a": "w-caching-food-and-tucking-cards", "t": "Caching food and tucking cards", "s": "Rules detail", "k": "rule", "x": "Cached food: food placed on a bird card. It can't be spent, but it's worth 1 point each at game end. Tucked cards: cards slid under a bird, for example by flocking birds. Each is worth 1 point ."}, {"g": "wingspan", "u": "wingspan/", "a": "w-egg-limit", "t": "Egg limit", "s": "Rules detail", "k": "rule", "x": "Each bird shows how many eggs it can hold. If every bird is full, extra eggs from the lay-eggs action are lost. Every egg on your birds is worth 1 point at the end."}, {"g": "wingspan", "u": "wingspan/", "a": "w-bonus-cards", "t": "Bonus cards", "s": "Rules detail", "k": "rule", "x": "You start with 1 and some birds give you more. Each card scores at game end if you meet its condition, for example points per bird of a certain kind. You can keep your bonus cards secret."}, {"g": "wingspan", "u": "wingspan/", "a": "w-green-goal-board-competitive", "t": "Green goal board (competitive)", "s": "Rules detail", "k": "rule", "x": "Rank players by how many of the round's target item they have. You need at least 1 to score. Round 1st 2nd 3rd 1 4 1 0 2 5 2 1 3 6 3 2 4 7 4 3 Ties: add up the points for the tied places and split them evenly, rounding down."}, {"g": "wingspan", "u": "wingspan/", "a": "w-blue-goal-board-friendlier", "t": "Blue goal board (friendlier)", "s": "Rules detail", "k": "rule", "x": "Score 1 point per target item , up to 5 points , no matter what others have."}, {"g": "wingspan", "u": "wingspan/", "a": "w-managing-the-bird-deck", "t": "Managing the bird deck", "s": "Rules detail", "k": "rule", "x": "If the deck runs out, shuffle the discards to form a new deck. Refill the tray at the end of each turn, not in the middle of drawing."}, {"g": "wingspan", "u": "wingspan/", "a": "w-faq-quick-hits", "t": "FAQ quick hits", "s": "Rules detail", "k": "rule", "x": "Can I skip brown powers? Yes, each one is optional. Is there a hand or food limit? No. Can I move birds? Not normally. Only bird powers can do that. Can I play a bird in a habitat it doesn't show? No. Can I use a die face for food it doesn't show? No. Use the 2-for-1 substitution when paying instead."}, {"g": "wingspan", "u": "wingspan/", "a": "w-end", "t": "Game end and winning", "s": "Section", "k": "section", "x": "Game end and winning The game ends… …after round 4, once everyone has used their 5 turns and the last goal is scored. Scoring Points printed on your birds Bonus cards you completed End-of-round goals 1 point per egg, cached food and tucked card Tie: the player with the most unused food tokens wins. If still tied, they share the win."}, {"g": "wingspan", "u": "wingspan/", "a": "w-goals", "t": "Green goal helper", "s": "Section", "k": "section", "x": "Green goal helper Round Round 1 (4 · 1 · 0) Round 2 (5 · 2 · 1) Round 3 (6 · 3 · 2) Round 4 (7 · 4 · 3) Your place 1st 2nd 3rd 4th or lower / none Players tied with you (including you) 4"}, {"g": "wingspan", "u": "wingspan/", "a": "w-calc", "t": "Score calculator", "s": "Section", "k": "section", "x": "Score calculator Bird points (printed) Bonus cards Goal: round 1 Goal: round 2 Goal: round 3 Goal: round 4 Eggs on birds Cached food Tucked cards Unused food (tie-break) 0 Clear"}];
